class EmbedContourTree(Node):

    def __init__(self, parent_node_id : str, ball_radius : float = 3.0, tube_radius : float = 1.5, color_scheme : List[str] = ["#002fff", "#758fff", "#ffdee7", "#ff0046", "#000000"]):

        if correctness_checks_on():
            if len(color_scheme) != 5:
                raise Exception("color_scheme should have 5 entries")

            for elt in color_scheme:
                if not is_hex_string(elt):
                    raise Exception(f"Element {elt} in color_scheme is not a hex string")

            del elt

        super().__init__(parent_node_id, types.ContourTree, types.ContourTreeEmbedding, locals(), False, True)

        self.ball_radius = ball_radius
        self.tube_radius = tube_radius
        self.color_scheme = color_scheme

    @classmethod
    def guardrails(cls):
        return [
            Guardrail(
                get_prompt("guardrails", "contour_tree_embedding"),
                "explicitly_requested_entire_contour_tree",
                "Set to True if the user explicitly requested the entire contour tree, including its vertices and edges. "
                "Set to False otherwise.",
                raise_on_tool_param_false(
                    "Cannot create this embedding because the user did not explicitly request the entire contour "
                    "tree, including its vertices and edges. Please ask whether they want the entire contour tree "
                    "or only its critical points / vertices."
                ),
            )
        ]

    @classmethod
    def chat_description(cls):
        return "queued embedding contour tree"

    @classmethod
    def description(cls):
        return 'Create a geometric embedding of the contour tree of a scalar field. '\
               'This will embed the entire contour tree including vertices and edges. To only visualize the '\
               'vertices / critical points, don\'t call this tool and instaed use the critical points computation.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type contour_tree that we are embedding.',
         'ball_radius': 'The radius of the vertices',
         'tube_radius': 'The radius of the edges',
         'color_scheme': 'A list of five hex strings corresponding to the colors for the '
                         'minima, 1-saddles, 2-saddles, maxima, and degenerate points, '
                         'respectively.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, types.MergeTreeEmbedding) and \
           self.parent_node.parent_node_id == other.parent_node.parent_node_id:

            return False, "Cannot visualize a field's merge and contour trees at the same time. They will overlap."

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        return types.ContourTreeEmbedding(parent_data.vertices, parent_data.edges, "CriticalType", color_list_to_lut(self.color_scheme), self.ball_radius, self.tube_radius )

