# used to export merge and contour trees
def _export_critical_point_tree(points, edges, points_filename, edges_filename, ct_array_name, scalar_array_name, ct_map, ct_map_name):

    if points_filename[-4:] != ".vtk":
        raise ValueError(f"Cannot save points to {points_filename}. Currently only legacy VTK files (.vtk) is supported.")

    if edges_filename[-4:] != ".vtk":
        raise ValueError(f"Cannot save edges to {edges_filename}. Currently only legacy VTK files (.vtk) is supported.")

    if len(ct_map) != 5:
        raise Exception(f"The size of {ct_map_name} must be exactly 5")

    os.makedirs(os.path.dirname(os.path.abspath(points_filename)), exist_ok=True)
    os.makedirs(os.path.dirname(os.path.abspath(edges_filename)), exist_ok=True)

    points_filter = categorical_map_filter(points, "CriticalType", ct_map, -1, ct_array_name)
    renameArrays = RenameArrays(Input=points_filter)
    renameArrays.PointArrays = ["Scalar", scalar_array_name]

    SaveData(points_filename, renameArrays)
    SaveData(edges_filename, edges)

    Delete(renameArrays)
    Delete(points_filter)

class Tree(NodeData):
